int cursor_read_header(struct cursor *c, struct header *out)
{
	if (!c->has_next)      /* guard clauses first: the body stays flat */
		return -ENODATA;
	if (c->len < HEADER_LEN)
		return -EBADMSG;

	out->kind = cursor_u16(c);   /* one level deep, no nested branches */
	out->len = cursor_u16(c);
	return 0;
}
